{
  "permissions": {
    "allow": ["Bash", "Edit"]
  },
  "enableAllProjectMcpServers": true,
  "extraKnownMarketplaces": {
    "dotai": {
      "source": {
        "source": "github",
        "repo": "udecode/dotai"
      }
    }
  },
  "enabledPlugins": {
    "ctx@dotai": true,
    "dotai@dotai": true,
    "fb@dotai": true,
    "notification@dotai": true,
    "media@dotai": true
  },
  "hooks": {
    "SessionStart": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "if command -v flashback &> /dev/null; then flashback session-start --context; elif [ -f \"$HOME/.claude/flashbacker/lib/cli.js\" ]; then node \"$HOME/.claude/flashbacker/lib/cli.js\" session-start --context; fi"
          }
        ]
      }
    ]
  }
}
